public class CohereReranker : IReranker
{
    private readonly HttpClient _httpClient;
    private readonly ILogger _logger;
    private const string Model = "rerank-v3.5";

    public async Task<List<DocumentChunk>> RerankAsync(
        string query, List<DocumentChunk> candidates, int topK = 5, CancellationToken ct = default)
    {
        if (candidates.Count <= topK) return candidates;

        var request = new
        {
            model = Model,
            query = query,
            documents = candidates.Select(c => c.Content).ToList(),
            top_k = topK
        };

        var response = await _httpClient.PostAsJsonAsync(
            "https://api.cohere.ai/v1/rerank", request, ct);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadFromJsonAsync<RerankResponse>(cancellationToken: ct);

        // Map rerank results back to documents
        var reranked = result.Results
            .OrderBy(r => r.Index) // Results are pre-sorted by relevance score
            .Select(r => candidates[r.Index])
            .Take(topK)
            .ToList();

        _logger.LogInformation("Reranked {Input} candidates to {TopK} results", candidates.Count, topK);
        return reranked;
    }
}

public class RerankResponse
{
    public List<RerankResult> Results { get; set; }
}

public class RerankResult
{
    public double Score { get; set; }
    public int Index { get; set; }
}

public class OnnxReranker : IReranker
{
    private readonly Lazy<InferenceSession> _session;
    private readonly Lazy<Tokenizer> _tokenizer;

    public OnnxReranker(string modelPath, string vocabPath)
    {
        _session = new Lazy<InferenceSession>(() =>
            new InferenceSession(modelPath));
        _tokenizer = new Lazy<Tokenizer>(() =>
            new Tokenizer(Tokenizer.Load(vocabPath)));
    }

    public async Task<List<DocumentChunk>> RerankAsync(
        string query, List<DocumentChunk> candidates, int topK = 5, CancellationToken ct = default)
    {
        var scored = new List<(DocumentChunk chunk, float score)>();

        foreach (var chunk in candidates)
        {
            // Cross-encoder: tokenize query + document together
            var encoded = _tokenizer.Value.Encode($"{query} [SEP] {chunk.Content}");
            var input = new List<NamedOnnxValue>
            {
                NamedOnnxValue.CreateFromTensor("input_ids", encoded.Ids.ToArray()),
                NamedOnnxValue.CreateFromTensor("attention_mask", encoded.AttentionMask.ToArray())
            };

            using var result = _session.Value.Run(input);
            var score = result.First().AsTensor<float>().GetValue(0);
            scored.Add((chunk, score));
        }

        return scored
            .OrderByDescending(s => s.score)
            .Take(topK)
            .Select(s => s.chunk)
            .ToList();
    }
}
